      postJson<{ generated: number; periods: Period[] }>(
        `/api/sheets/${encodeURIComponent(sheet)}/rollover-undo`,
        { user },
      ),
    onSuccess: (saved) => {
      queryClient.setQueryData(periodsKey(sheet), saved.periods);
      void queryClient.invalidateQueries({ queryKey: openingsKey(sheet) });
    },
  });
  const generated = [generate, generateFy, generateQuarters].reduce((a, b) => (b.submittedAt > a.submittedAt ? b : a));
  const resetGenerated = () => {
    generate.reset();
    generateFy.reset();
    generateQuarters.reset();
  };
  // Close a period (open or soft-closed), soft-close an open one, or reopen a closed or soft-closed one (each by the roles the sheet's permission allows; by default
  // close by clerk and steward, reopen by a steward only).
  const act = useMutation({
    mutationFn: ({ name, action }: { name: string; action: 'close' | 'soft-close' | 'reopen' | 'lock' | 'unlock' }) =>
      postJson<Period[]>(
        `/api/sheets/${encodeURIComponent(sheet)}/periods/${encodeURIComponent(name)}/${action}`,
        { user },
      ),
    onSuccess: (saved) => queryClient.setQueryData(periodsKey(sheet), saved),
  });
  return (
    <>
      <table data-testid="periods">
        <thead>
          <tr>
            <th>Period</th>
            <th>From</th>
            <th>To</th>
            <th>Due</th>
            <th>Closed</th>
            <th>FY</th>
            <th>Cap</th>
            <th>Locked</th>
            <th></th>
          </tr>
        </thead>
        <tbody>
          {periods.map((p) => (
            <tr key={p.name} data-testid={`period-row-${p.name}`}>
              <td data-testid="period-name">{p.name}</td>
              <td data-testid="period-from">{p.from}</td>
              <td data-testid="period-to">{p.to}</td>
              <td data-testid="period-due-total">{formatCents(dueTotalOf(p))}</td>
              <td data-testid="period-closed">{p.closed ? 'yes' : p.softClosed ? 'soft' : 'no'}</td>
              <td data-testid="period-fy">{fiscalYearOf(p.from, fiscalStart)}</td>
              <td data-testid="period-cap">{p.cap}</td>
              <td data-testid="period-locked">{p.locked ? 'yes' : 'no'}</td>
              <td>
                {!p.closed && (
                  <button
                    type="button"
                    data-testid="period-close"
                    onClick={() => {
                      act.reset();
                      act.mutate({ name: p.name, action: 'close' });
                    }}
                  >
                    Close
                  </button>
                )}{' '}
                <button
                  type="button"
                  data-testid="period-soft-close"
                  onClick={() => {
                    act.reset();
                    act.mutate({ name: p.name, action: 'soft-close' });
                  }}
                >
                  Soft close
                </button>{' '}
                <button
                  type="button"
                  data-testid="period-reopen"
                  onClick={() => {
                    act.reset();
                    act.mutate({ name: p.name, action: 'reopen' });
                  }}
                >
                  Reopen
                </button>{' '}
                <button
                  type="button"
                  data-testid="period-lock"
                  onClick={() => {
                    act.reset();
                    act.mutate({ name: p.name, action: 'lock' });
                  }}
                >
                  Lock
                </button>{' '}
                <button
                  type="button"
                  data-testid="period-unlock"
                  onClick={() => {
                    act.reset();
                    act.mutate({ name: p.name, action: 'unlock' });
                  }}
                >
                  Unlock
                </button>
                {act.isError && act.variables?.name === p.name && (
                  <span data-testid="period-error" role="alert">
                    {act.variables.action === 'lock'
                      ? ' Could not lock the period: only a steward can lock it, and only while it is unlocked.'
                      : act.variables.action === 'unlock'
                      ? ' Could not unlock the period: only a steward can unlock it, and only while it is locked.'
                      : act.variables.action === 'reopen'
                      ? ' Could not reopen the period: only a role the sheet allows to reopen (by default a steward) can reopen it, and only while it is closed or soft-closed and not locked.'
                      : act.variables.action === 'soft-close'
                      ? ' Could not soft-close the period: only a role the sheet allows to close can soft-close it, and only while it is open.'
                      : ' Could not close the period: only a role the sheet allows to close can close it, and only while it is open or soft-closed.'}
                  </span>
                )}
              </td>
            </tr>
          ))}
        </tbody>
      </table>
      <form
        data-testid="period-form"
        onSubmit={(e) => {
          e.preventDefault();
          submitOnce(() => {
            add.reset();
            return add.mutateAsync({ name: name.trim(), from: from.trim(), to: to.trim(), cap: cap.trim() });
          });
        }}
      >
        <input
          data-testid="period-form-name"
          value={name}
          placeholder="Period name"
          onChange={(e) => {
            setName(e.target.value);
            add.reset();
          }}
        />{' '}
        <input
          data-testid="period-form-from"
          value={from}
          placeholder="From (YYYY-MM-DD)"
          onChange={(e) => {
            setFrom(e.target.value);
            add.reset();
          }}
        />{' '}
        <input
          data-testid="period-form-to"
          value={to}
          placeholder="To (YYYY-MM-DD)"
          onChange={(e) => {
            setTo(e.target.value);
            add.reset();
          }}
        />{' '}
        <input
          data-testid="period-form-cap"
          value={cap}
          placeholder="Cap per person (blank for none)"
          onChange={(e) => {
            setCap(e.target.value);
            add.reset();
          }}
        />{' '}
        <button type="submit" data-testid="period-form-submit">Add period</button>
        {add.isError && <span data-testid="period-form-error" role="alert"> Could not add the period: it needs a name not already on the sheet and a from-date on or before its to-date (YYYY-MM-DD), not overlapping another period, and a cap that is blank or a whole number of at least 1.</span>}
      </form>
      <form
        data-testid="period-generate-form"
        onSubmit={(e) => {
          e.preventDefault();
          submitOnce(() => {
            resetGenerated();
            return generate.mutateAsync({ from: genFrom.trim(), to: genTo.trim() });
          });
        }}
      >
        <input
          data-testid="period-generate-from"
          value={genFrom}
          placeholder="From (YYYY-MM-DD)"
          onChange={(e) => {
            setGenFrom(e.target.value);
            generate.reset();
          }}
        />{' '}
        <input
          data-testid="period-generate-to"
          value={genTo}
          placeholder="To (YYYY-MM-DD)"
          onChange={(e) => {
            setGenTo(e.target.value);
            generate.reset();
          }}
        />{' '}
        <button type="submit" data-testid="period-generate">Generate monthly periods</button>
        {generated.isSuccess && (
          <>
            {' '}
            Made <span data-testid="period-generated">{generated.data.generated}</span>
          </>
        )}
        {generated.isError && (
          <span data-testid="period-generate-error" role="alert">
            {' '}
            {generated === generateFy
              ? 'Could not generate the fiscal year: it must be a year (YYYY).'
              : generated === generateQuarters
              ? 'Could not generate the quarters: the year must be a year (YYYY).'
              : 'Could not generate periods: the to-date must be on or after the from-date (YYYY-MM-DD).'}
          </span>
        )}
      </form>
      <form
        data-testid="period-generate-fy-form"
        onSubmit={(e) => {
          e.preventDefault();
          submitOnce(() => {
            resetGenerated();
            return generateFy.mutateAsync({ year: fyYear.trim() });
          });
        }}
      >
        <input
          data-testid="period-generate-fy-year"
          value={fyYear}
          placeholder="Fiscal year (YYYY)"
          onChange={(e) => {
            setFyYear(e.target.value);
            generateFy.reset();
          }}
        />{' '}
        <button type="submit" data-testid="period-generate-fy">Generate fiscal year</button>
      </form>
      <form
        data-testid="period-generate-quarters-form"
        onSubmit={(e) => {
          e.preventDefault();
          submitOnce(() => {
            resetGenerated();
            return generateQuarters.mutateAsync({ year: qYear.trim() });
          });
        }}
      >
        <input
          data-testid="period-generate-quarters-year"
          value={qYear}
          placeholder="Year (YYYY)"
          onChange={(e) => {
            setQYear(e.target.value);
            generateQuarters.reset();
          }}
        />{' '}
        <button type="submit" data-testid="period-generate-quarters">Generate quarters</button>
      </form>
      <form
        data-testid="rollover-form"
        onSubmit={(e) => {
          e.preventDefault();
          submitOnce(() => {
            rollover.reset();
            rolloverUndo.reset();
            return rollover.mutateAsync({ year: rollYear.trim() });
          });
        }}
      >
        <input
          data-testid="rollover-year"
          value={rollYear}
          placeholder="Fiscal year to roll over (YYYY)"
          onChange={(e) => {
            setRollYear(e.target.value);
            rollover.reset();
            rolloverUndo.reset();
          }}
        />{' '}
        <button type="submit" data-testid="rollover">Roll the year over</button>{' '}
        <button
          type="button"
          data-testid="rollover-undo"
          onClick={() =>
            submitOnce(() => {
              rollover.reset();
              rolloverUndo.reset();
              return rolloverUndo.mutateAsync();
            })
          }
        >
          Undo the last rollover
        </button>
        {rollover.isSuccess && (
          <>
            {' '}
            Made <span data-testid="rollover-made">{rollover.data.generated}</span>
          </>
        )}
        {rollover.isError && (
          <span data-testid="rollover-error" role="alert">
            {' '}
            Could not roll the year over: only a steward can, of a year (YYYY) with periods on the sheet.
          </span>
        )}
        {rolloverUndo.isError && (
          <span data-testid="rollover-error" role="alert">
            {' '}
            Could not undo the rollover: only the steward who made it can, on the day it was made, while no claim
            belongs to a period it generated.
          </span>
        )}
      </form>
      <ImportOpenings />
    </>
  );
}
import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
